// components/pages/Home.js
import React, { useState, useEffect } from 'react';
import { apiCall, canSeeCommission } from '../../utils/api';

const Home = ({ showToast, currentUserRole }) => {
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lowUnitsCount, setLowUnitsCount] = useState(0);

  const loadData = async () => {
    setLoading(true);
    try {
      const statsResult = await apiCall('getStats');
      const tillsResult = await apiCall('getTills');
      
      if (statsResult.success) {
        setStats(statsResult);
        const tills = tillsResult.tills || [];
        const lowCount = tills.filter(t => t.units < 50 && t.status === 'active').length;
        setLowUnitsCount(lowCount);
      }
    } catch (error) {
      console.error('Error loading stats:', error);
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleRefresh = () => {
    loadData();
    showToast('Dashboard refreshed!');
  };

  if (loading) {
    return (
      <div className="loading">
        <i className="fas fa-spinner fa-pulse"></i> Loading dashboard...
      </div>
    );
  }

  const activeTills = stats?.activeTills || 0;
  const actualCommission = activeTills * 200;

  return (
    <>
      <h3 className="section-title">
        <i className="fas fa-chart-pie"></i> Executive Dashboard
        <button className="btn-secondary" onClick={handleRefresh} style={{ width: 'auto', padding: '8px 20px' }}>
          <i className="fas fa-sync-alt"></i> Refresh
        </button>
      </h3>
      <div className="stats-grid">
        <div className="stat-card">
          <div className="stat-icon"><i className="fas fa-users"></i></div>
          <div className="stat-value">{stats?.totalLines || 0}</div>
          <div className="stat-label">Total Lines Registered</div>
        </div>
        <div className="stat-card">
          <div className="stat-icon"><i className="fas fa-cash-register"></i></div>
          <div className="stat-value">{activeTills}</div>
          <div className="stat-label">Active Tills</div>
        </div>
        <div className="stat-card">
          <div className="stat-icon"><i className="fas fa-exclamation-triangle"></i></div>
          <div className="stat-value">{lowUnitsCount}</div>
          <div className="stat-label">Low Units Alert</div>
        </div>
        {canSeeCommission(currentUserRole) && (
          <div className="stat-card">
            <div className="stat-icon"><i className="fas fa-chart-line"></i></div>
            <div className="stat-value">KES {actualCommission.toLocaleString()}</div>
            <div className="stat-label">Actual Commission</div>
          </div>
        )}
      </div>
    </>
  );
};

export default Home;
